/* prog21_date_validator.c
 * Reimplementation of the original program's behaviour.
 * The program expects a single command-line argument representing a date
 * in the format YYYY-MM-DD. It prints "VALID" if the argument is a correct
 * Gregorian calendar date, otherwise it prints "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

/* Return true if the given year is a leap year in the Gregorian calendar */
static bool is_leap_year(int year)
{
    if (year % 4 != 0) return false;
    if (year % 100 != 0) return true;
    return (year % 400 == 0);
}

/* Return the number of days in the given month of the given year */
static int days_in_month(int year, int month)
{
    static const int days[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };
    if (month == 2 && is_leap_year(year))
        return 29;
    return days[month - 1];
}

/* Validate the date string; returns true if it is a correct date */
static bool validate_date(const char *s)
{
    /* 1. Basic format checks */
    if (strlen(s) != 10)
        return false;
    if (s[4] != '-' || s[7] != '-')
        return false;
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;          /* the two dashes */
        if (!isdigit((unsigned char)s[i]))
            return false;
    }

    /* 2. Convert to integers */
    int year  = (s[0] - '0') * 1000 +
                (s[1] - '0') * 100  +
                (s[2] - '0') * 10   +
                (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* 3. Range checks */
    if (month < 1 || month > 12)
        return false;
    if (day < 1 || day > days_in_month(year, month))
        return false;

    return true;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
